import{_ as l,a0 as o,w as d,s as p,I as a,x as s,a1 as n,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"網絡地址轉換（NAT）之連接跟蹤工具 | LCTT x X-CMD","titleTemplate":false,"description":"網絡地址轉換（NAT）之連接跟蹤工具 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"網絡地址轉換（NAT）之連接跟蹤工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"網絡地址轉換（NAT）之連接跟蹤工具 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210212 Network address translation part 2 - the conntrack tool","title":"網絡地址轉換（NAT）之連接跟蹤工具","tag":"202105","desc":""},"relativePath":"202105/20210212 Network address translation part 2 - the conntrack tool.md","filePath":"[post].md"}'),k={name:"202105/20210212 Network address translation part 2 - the conntrack tool.md"};function u(g,t,h,c,f,b){const e=o("Link");return d(),p("div",null,[t[35]||(t[35]=a("h1",{id:"網絡地址轉換-nat-之連接跟蹤工具",tabindex:"-1"},[s("網絡地址轉換（NAT）之連接跟蹤工具 "),a("a",{class:"header-anchor",href:"#網絡地址轉換-nat-之連接跟蹤工具","aria-label":"Permalink to “網絡地址轉換（NAT）之連接跟蹤工具”"},"​")],-1)),t[36]||(t[36]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/09/120958wwocez99o2nofw8s.jpg",alt:""})],-1)),a("p",null,[t[1]||(t[1]=s("這是有關",-1)),t[2]||(t[2]=a("ruby",null,[s("網絡地址轉換"),a("rt",null,"network address translation")],-1)),t[3]||(t[3]=s("（NAT）的系列文章中的第二篇。之前的第一篇文章介紹了 ",-1)),n(e,{href:"https://linux.cn/article-13364-1.html"},{default:i(()=>[...t[0]||(t[0]=[s("如何使用 iptables/nftables 的報文跟蹤功能",-1)])]),_:1}),t[4]||(t[4]=s(" 來定位 NAT 相關的連接問題。作為第二部分，本文介紹 ",-1)),t[5]||(t[5]=a("code",null,"conntrack",-1)),t[6]||(t[6]=s(" 命令，它允許你查看和修改被跟蹤的連接。",-1))]),t[37]||(t[37]=r(`<h3 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h3><p>通過 iptables 或 nftables 配置的 NAT 建立在 netfilters 連接跟蹤子系統之上。<code>conntrack</code> 命令作為 “conntrack-tools” 軟件包的一部分，用於查看和更改連接狀態表。</p><h3 id="連接跟蹤狀態表" tabindex="-1">連接跟蹤狀態表 <a class="header-anchor" href="#連接跟蹤狀態表" aria-label="Permalink to “連接跟蹤狀態表”">​</a></h3><p>連接跟蹤子系統會跟蹤它看到的所有報文流。運行 <code>sudo conntrack -L</code> 可查看其內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tcp 6 43184 ESTABLISHED src=192.168.2.5 dst=10.25.39.80 sport=5646 dport=443 src=10.25.39.80 dst=192.168.2.5 sport=443 dport=5646 [ASSURED] mark=0 use=1</span></span>
<span class="line"><span>tcp 6 26 SYN_SENT src=192.168.2.5 dst=192.168.2.10 sport=35684 dport=443 [UNREPLIED] src=192.168.2.10 dst=192.168.2.5 sport=443 dport=35684 mark=0 use=1</span></span>
<span class="line"><span>udp 17 29 src=192.168.8.1 dst=239.255.255.250 sport=48169 dport=1900 [UNREPLIED] src=239.255.255.250 dst=192.168.8.1 sport=1900 dport=48169 mark=0 use=1</span></span></code></pre></div><p>上述顯示結果中，每行表示一個連接跟蹤項。你可能會注意到，每行相同的地址和端口號會出現兩次，而且第二次出現的源地址/端口對和目標地址/端口對會與第一次正好相反！這是因為每個連接跟蹤項會先後兩次被插入連接狀態表。第一個四元組（源地址、目標地址、源端口、目標端口）記錄的是原始方向的連接信息，即發送者發送報文的方向。而第二個四元組則記錄的是連接跟蹤子系統期望收到的對端回覆報文的連接信息。這解決了兩個問題：</p><ol><li>如果報文匹配到一個 NAT 規則，例如 IP 地址偽裝，相應的映射信息會記錄在鏈接跟蹤項的回覆方向部分，並自動應用於同一條流的所有後續報文。</li><li>即使一條流經過了地址或端口的轉換，也可以成功在連接狀態表中查找到回覆報文的四元組信息。</li></ol>`,7)),a("p",null,[t[8]||(t[8]=s("原始方向的（第一個顯示的）四元組信息永遠不會改變：它就是發送者發送的連接信息。NAT 操作只會修改回覆方向（第二個）四元組，因為這是接受者看到的連接信息。修改第一個四元組沒有意義：netfilter 無法控制發起者的連接狀態，它只能在收到/轉發報文時對其施加影響。當一個報文未映射到現有連接表項時，連接跟蹤可以為其新建一個表項。對於 UDP 報文，該操作會自動進行。對於 TCP 報文，連接跟蹤可以配置為只有 TCP 報文設置了 ",-1)),n(e,{href:"https://en.wikipedia.org/wiki/Transmission_Control_Protocol#TCP_segment_structure"},{default:i(()=>[...t[7]||(t[7]=[s("SYN 標誌位",-1)])]),_:1}),t[9]||(t[9]=s(" 才新建表項。默認情況下，連接跟蹤會允許從流的中間報文開始創建，這是為了避免對啓用連接跟蹤之前就存在的流處理出現問題。",-1))]),t[38]||(t[38]=r('<h3 id="連接跟蹤狀態表和-nat" tabindex="-1">連接跟蹤狀態表和 NAT <a class="header-anchor" href="#連接跟蹤狀態表和-nat" aria-label="Permalink to “連接跟蹤狀態表和 NAT”">​</a></h3><p>如上一節所述，回覆方向的四元組包含 NAT 信息。你可以通過命令過濾輸出經過源地址 NAT 或目標地址 NAT 的連接跟蹤項。通過這種方式可以看到一個指定的流經過了哪種類型的 NAT 轉換。例如，運行 <code>sudo conntrack -L -p tcp –src-nat</code> 可顯示經過源 NAT 的連接跟蹤項，輸出結果類似於以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tcp 6 114 TIME_WAIT src=10.0.0.10 dst=10.8.2.12 sport=5536 dport=80 src=10.8.2.12 dst=192.168.1.2 sport=80 dport=5536 [ASSURED]</span></span></code></pre></div>',3)),a("p",null,[t[11]||(t[11]=s("這個連接跟蹤項表示一條從 10.0.0.10:5536 到 10.8.2.12:80 的連接。與前面示例不同的是，回覆方向的四元組不是原始方向四元組的簡單翻轉：源地址已修改。目標主機（10.8.2.12）將回複數據包發送到 192.168.1.2，而不是 10.0.0.10。每當 10.0.0.10 發送新的報文時，具有此連接跟蹤項的路由器會將源地址替換為 192.168.1.2。當 10.8.2.12 發送回覆報文時，該路由器將目的地址修改回 10.0.0.10。上述源 NAT 行為源自一條 ",-1)),n(e,{href:"https://wiki.nftables.org/wiki-nftables/index.php/Performing_Network_Address_Translation_(NAT)#Masquerading"},{default:i(()=>[...t[10]||(t[10]=[s("NFT 偽裝",-1)])]),_:1}),t[12]||(t[12]=s(" 規則：",-1))]),t[39]||(t[39]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inet nat postrouting meta oifname &quot;veth0&quot; masquerade</span></span></code></pre></div><p>其他類型的 NAT 規則，例如目標地址 DNAT 規則或重定向規則，其連接跟蹤項也會以類似的方式顯示，回覆方向四元組的遠端地址或端口與原始方向四元組的遠端地址或端口不同。</p><h3 id="連接跟蹤擴展" tabindex="-1">連接跟蹤擴展 <a class="header-anchor" href="#連接跟蹤擴展" aria-label="Permalink to “連接跟蹤擴展”">​</a></h3><p>連接跟蹤的記帳功能和時間戳功能是兩個有用的擴展功能。運行 <code>sudo sysctl net.netfilter.nf_conntrack_acct=1</code> 可以在運行 <code>sudo conntrack -L</code> 時顯示每個流經過的字節數和報文數。運行 <code>sudo sysctl net.netfilter.nf_conntrack_timestamp=1</code> 為每個連接記錄一個開始時間戳，之後每次運行 <code>sudo conntrack -L</code> 時都可以顯示這個流從開始經過了多少秒。在上述命令中增加 <code>–output ktimestamp</code> 選項也可以看到流開始的絕對時間。</p><h3 id="插入和更改連接跟蹤項" tabindex="-1">插入和更改連接跟蹤項 <a class="header-anchor" href="#插入和更改連接跟蹤項" aria-label="Permalink to “插入和更改連接跟蹤項”">​</a></h3><p>你可以手動為狀態表添加連接跟蹤項，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo conntrack -I -s 192.168.7.10 -d 10.1.1.1 --protonum 17 --timeout 120 --sport 12345 --dport 80</span></span></code></pre></div><p>這項命令通常被 conntrackd 用於狀態複製，即將主防火牆的連接跟蹤項複製到備用防火牆系統。於是當切換髮生的時候，備用系統可以接管已經建立的連接且不會造成中斷。連接跟蹤還可以存儲報文的帶外元數據，例如連接跟蹤標記和連接跟蹤標籤。可以用更新選項（<code>-U</code>）來修改它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo conntrack -U -m 42 -p tcp</span></span></code></pre></div><p>這條命令將所有的 TCP 流的連接跟蹤標記修改為 42。</p><h3 id="刪除連接跟蹤項" tabindex="-1">刪除連接跟蹤項 <a class="header-anchor" href="#刪除連接跟蹤項" aria-label="Permalink to “刪除連接跟蹤項”">​</a></h3><p>在某些情況下，你可能想從狀態表中刪除條目。例如，對 NAT 規則的修改不會影響表中已存在流的經過報文。因此對 UDP 長連接（例如像 VXLAN 這樣的隧道協議），刪除表項可能很有意義，這樣新的 NAT 轉換規則才能生效。可以通過 <code>sudo conntrack -D</code> 命令附帶可選的地址和端口列表選項，來刪除相應的表項，如下例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo conntrack -D -p udp  --src 10.0.12.4 --dst 10.0.0.1 --sport 1234 --dport 53</span></span></code></pre></div><h3 id="連接跟蹤錯誤計數" tabindex="-1">連接跟蹤錯誤計數 <a class="header-anchor" href="#連接跟蹤錯誤計數" aria-label="Permalink to “連接跟蹤錯誤計數”">​</a></h3><p><code>conntrack</code> 也可以輸出統計數字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sudo conntrack -S</span></span>
<span class="line"><span>cpu=0 found=0 invalid=130 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=10</span></span>
<span class="line"><span>cpu=1 found=0 invalid=0 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=0</span></span>
<span class="line"><span>cpu=2 found=0 invalid=0 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=1</span></span>
<span class="line"><span>cpu=3 found=0 invalid=0 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=0</span></span></code></pre></div><p>大多數計數器將為 0。<code>Found</code> 和 <code>insert</code> 數將始終為 0，它們只是為了後向兼容。其他錯誤計數包括：</p><ul><li><code>invalid</code>：報文既不匹配已有連接跟蹤項，也未創建新連接。</li><li><code>insert_failed</code>：報文新建了一個連接，但插入狀態表時失敗。這在 NAT 引擎在偽裝時恰好選擇了重複的源地址和端口時可能出現。</li><li><code>drop</code>：報文新建了一個連接，但是沒有可用的內存為其分配新的狀態條目。</li><li><code>early_drop</code>：連接跟蹤表已滿。為了接受新的連接，已有的未看到雙向報文的連接被丟棄。</li><li><code>error</code>：icmp(v6) 收到與已知連接不匹配的 icmp 錯誤數據包。</li><li><code>search_restart</code>：查找過程由於另一個 CPU 的插入或刪除操作而中斷。</li><li><code>clash_resolve</code>：多個 CPU 試圖插入相同的連接跟蹤條目。</li></ul>`,18)),a("p",null,[t[14]||(t[14]=s("除非經常發生，這些錯誤條件通常無害。一些錯誤可以通過針對預期工作負載調整連接跟蹤子系統的參數來降低其發生概率，典型的配置包括 ",-1)),t[15]||(t[15]=a("code",null,"net.netfilter.nf_conntrack_buckets",-1)),t[16]||(t[16]=s(" 和 ",-1)),t[17]||(t[17]=a("code",null,"net.netfilter.nf_conntrack_max",-1)),t[18]||(t[18]=s(" 參數。可在 ",-1)),n(e,{href:"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/Documentation/networking/nf_conntrack-sysctl.rst"},{default:i(()=>[...t[13]||(t[13]=[s("nf_conntrack-sysctl 文檔",-1)])]),_:1}),t[19]||(t[19]=s(" 中查閲相應配置參數的完整列表。",-1))]),t[40]||(t[40]=r('<p>當報文狀態是 <code>invalid</code> 時，請使用 <code>sudo sysctl net.netfilter.nf_conntrack_log_invalid=255</code> 來獲取更多信息。例如，當連接跟蹤遇到一個所有 TCP 標誌位均為 0 的報文時，將記錄以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nf_ct_proto_6: invalid tcp flag combination SRC=10.0.2.1 DST=10.0.96.7 LEN=1040 TOS=0x00 PREC=0x00 TTL=255 ID=0 PROTO=TCP SPT=5723 DPT=443 SEQ=1 ACK=0</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文介紹瞭如何檢查連接跟蹤表和存儲在跟蹤流中的 NAT 信息。本系列的下一部分將延伸討論連接跟蹤工具和連接跟蹤事件框架。</p><hr>',5)),a("p",null,[t[21]||(t[21]=s("via: ",-1)),n(e,{href:"https://fedoramagazine.org/network-address-translation-part-2-the-conntrack-tool/"},{default:i(()=>[...t[20]||(t[20]=[s("https://fedoramagazine.org/network-address-translation-part-2-the-conntrack-tool/",-1)])]),_:1})]),a("p",null,[t[26]||(t[26]=s("作者：",-1)),n(e,{href:"https://fedoramagazine.org/author/strlen/"},{default:i(()=>[...t[22]||(t[22]=[s("Florian Westphal",-1)])]),_:1}),t[27]||(t[27]=s(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[23]||(t[23]=[s("lujun9972",-1)])]),_:1}),t[28]||(t[28]=s(" 譯者：",-1)),n(e,{href:"https://github.com/cooljelly"},{default:i(()=>[...t[24]||(t[24]=[s("cooljelly",-1)])]),_:1}),t[29]||(t[29]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[25]||(t[25]=[s("wxy",-1)])]),_:1})]),a("p",null,[t[32]||(t[32]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[30]||(t[30]=[s("LCTT",-1)])]),_:1}),t[33]||(t[33]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...t[31]||(t[31]=[s("Linux中國",-1)])]),_:1}),t[34]||(t[34]=s(" 榮譽推出",-1))])])}const N=l(k,[["render",u]]);export{C as __pageData,N as default};
